datalog.authorizer:
// AASC frozen authorizer Gamma, v1 (MSc profile; ADR 0016).
// Facts injected per evaluation by the evaluating side, never by the token:
//   operation(<action>, <resource>)   exactly one candidate x in Omega per run
//   time(<now>), request_audience(<audience>), request_task(<task_id>)
check if time($t), expiry($e), $t <= $e;
check if request_audience($aud), token_audience($aud);
check if request_task($task), token_task($task);
allow if operation($action, $resource), right($action, $resource);

datalog.authority_block_template:
// Block 0, signed by kappa. One right/2 fact per element of C_0 = U_task.
right("<action>", "<resource>");
token_audience("<audience>");
token_task("<task_id>");
expiry(<instant>);

datalog.attenuation_block_template:
// Block i >= 1, appended offline by the holder of hop i-1.
// One scope/2 fact per element of C_i, plus the check that consumes them.
// The check and its facts sit in the SAME block, so default block scoping
// trusts them; no later block's facts are visible to any earlier check.
scope("<action>", "<resource>");
check if operation($action, $resource), scope($action, $resource);
